import { Component, computed, input, model, output, TemplateRef } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import {
  TablerIconComponent, IconTable, IconLayoutGrid, IconLayoutKanban, IconChartBar,
} from '@tabler/icons-angular';
import { HrmGrid, HrmGridColumn, HrmGridSort } from './hrm-grid';
import { HrmBoard, HrmBoardGroup } from './hrm-board';
import { HrmGantt } from './hrm-gantt';
import { HrmDataToolbar } from './hrm-data-toolbar';
import { HrmSortColumn } from './hrm-sort-config';
import { HrmRowGrouping } from './hrm-row-grouping';
import { HrmRowGroupLevel } from './hrm-data-config.types';

type Row = Record<string, unknown>;
/** Chế độ xem dữ liệu. */
export type HrmDataViewMode = 'table' | 'card' | 'kanban' | 'gantt';

/** hrm-data-view — "Chế độ xem dữ liệu": 1 tập dữ liệu, nhiều cách xem (Bảng/Thẻ/Kanban/Gantt),
 *  đổi qua thanh tab kiểu ClickUp. Click bản ghi phát (openRecord) để mở chi tiết (ghép hrm-detail-peek).
 *  Slot [dvActions] cho bộ lọc bên trái. Nhãn tab do caller cấp (i18n). Toàn token → tự Light/Dark.
 *
 *  <hrm-data-view [columns]="cols" [data]="rows" [modes]="['table','kanban','gantt']" [(mode)]="mode"
 *     groupBy="status" [boardGroups]="cols" startField="start" endField="end" progressField="progress"
 *     [cardTemplate]="cardTpl" (openRecord)="open($event)"><div dvActions>…lọc…</div></hrm-data-view> */
@Component({
  selector: 'hrm-data-view',
  imports: [NgTemplateOutlet, TablerIconComponent, HrmGrid, HrmBoard, HrmGantt, HrmDataToolbar, HrmRowGrouping],
  template: `
    <!-- [toolbar] BẬT → gói toolbar + bảng trong 1 PANEL viền chung (toolbar gạch dưới, bảng phẳng)
         như template hrm-list-page → toolbar DÍNH bảng, không rời. Kanban/gantt: panel phẳng (board tự là thẻ). -->
    <div [class.dv-panel]="toolbar()" [class.dv-panel--flat]="toolbar() && isFlat()">
      <div class="dv-bar" [class.dv-bar--attached]="toolbar()">
        @if (toolbar()) {
          <hrm-data-toolbar class="dv-tb"
            [count]="viewData().length" [countLabel]="countLabel()"
            [searchable]="searchable()" [(search)]="search" [searchPlaceholder]="searchPlaceholder()" (searchChange)="searchChange.emit($event)"
            [filterable]="filterable()" (filterClick)="filterClick.emit()"
            [exportable]="exportable()" (exportClick)="exportClick.emit()"
            [sortColumns]="mode() === 'table' ? toolbarColumns() : []" [(sortLevels)]="sortLevels"
            [columns]="mode() === 'table' ? toolbarColumns() : []" [(hiddenKeys)]="hiddenKeys">
            <ng-content select="[dvActions]" ngProjectAs="[tbFilters]" />
          </hrm-data-toolbar>
        } @else {
          <div class="dv-actions"><ng-content select="[dvActions]" /></div>
          <div class="dv-spacer"></div>
        }
        @if (tabs().length > 1) {
          <div class="dv-tabs" role="tablist">
            @for (t of tabs(); track t.mode) {
              <button type="button" class="dv-tab" [class.is-on]="mode() === t.mode"
                role="tab" [attr.aria-selected]="mode() === t.mode" [attr.aria-label]="t.label || null"
                (click)="mode.set(t.mode)">
                <tabler-icon [icon]="$any(t.icon)" [size]="16" />
                @if (t.label) { <span class="dv-tab-t">{{ t.label }}</span> }
              </button>
            }
          </div>
        }
      </div>

      <div [class.dv-view]="toolbar()">
      @switch (mode()) {
      @case ('table') {
        @if (showGroupPanel()) {
          <hrm-row-grouping class="dv-grp" [columns]="rowGroupColumns()" [(levels)]="rowGroups" [dropListId]="groupDropId" />
        }
        <hrm-grid [columns]="columns()" [data]="viewData()" [rowKey]="rowKey()" [minWidth]="tableMinWidth()"
          [size]="size()" [selectable]="selectable()" [showPagination]="false"
          [customizable]="customizable()" [reorderable]="reorderable()" [resizable]="resizable()"
          [(sortLevels)]="sortLevels" [(hiddenKeys)]="hiddenKeys"
          [rowGroups]="mode() === 'table' ? rowGroups() : []"
          [columnGroups]="mode() === 'table' ? columnGroups() : []"
          [groupConnectedTo]="(showGroupPanel() && mode() === 'table') ? [groupDropId] : []"
          [groupLabelFormatter]="groupLabelFormatter()"
          [selectedKeys]="selectedKeys()" (selectedKeysChange)="selectedKeys.set($event)"
          (rowClick)="openRecord.emit($event)" />
      }
      @case ('card') {
        <div class="dv-cards" [style.--dv-min.px]="cardMin()">
          @for (row of viewData(); track rowId(row)) {
            <button type="button" class="dv-card" [class.is-sel]="isSel(row)" (click)="openRecord.emit(row)">
              @if (selectable()) {
                <label class="dv-check" (click)="$event.stopPropagation()">
                  <input type="checkbox" [checked]="isSel(row)"
                    (change)="toggleSel(row, $any($event.target).checked)" />
                </label>
              }
              @if (cardTemplate()) {
                <ng-container [ngTemplateOutlet]="cardTemplate()!" [ngTemplateOutletContext]="{ $implicit: row }" />
              }
            </button>
          }
        </div>
      }
      @case ('kanban') {
        <hrm-board [data]="viewData()" [groupBy]="groupBy()" [groups]="boardGroups()" [rowKey]="rowKey()"
          [cardTemplate]="boardCard()" [addLabel]="boardAddLabel()"
          [selectable]="selectable()" [selectedKeys]="selectedKeys()" (selectedKeysChange)="selectedKeys.set($event)"
          (cardClick)="openRecord.emit($event)" (groupChange)="groupChange.emit($event)"
          (addCard)="boardAdd.emit($event)" />
      }
      @case ('gantt') {
        <hrm-gantt [data]="viewData()" [startField]="startField()" [endField]="endField()"
          [labelField]="ganttLabelField()" [progressField]="progressField()" [rowKey]="rowKey()"
          [labelHeader]="ganttHeader()" [dateHeader]="ganttDateHeader()"
          [labelTemplate]="ganttLabelTemplate()" [barTone]="ganttBarTone()"
          [selectable]="selectable()" [selectedKeys]="selectedKeys()" (selectedKeysChange)="selectedKeys.set($event)"
          (barClick)="openRecord.emit($event)" />
      }
      }
      </div>
    </div>
  `,
  host: { class: 'hrm-data-view' },
  styles: [`
    /* height:100% để view dạng board/gantt lấp đầy vùng chứa (parent cao auto → coi như auto, an toàn). */
    :host { display: block; height: 100%; min-height: 0; }
    .dv-bar { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; flex-wrap: wrap; }
    .dv-tb { flex: 1 1 320px; min-width: 0; }
    .dv-actions { display: flex; align-items: center; gap: 8px; min-width: 0; }
    .dv-spacer { flex: 1; }

    /* ── [toolbar] BẬT: PANEL viền chung (nhân bản hrm-list-page) → toolbar DÍNH bảng ── */
    .dv-panel {
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
      overflow: hidden; display: flex; flex-direction: column; min-height: 0;
    }
    /* Toolbar attached: gạch dưới ngăn với bảng, KHÔNG margin (dính), padding gọn. */
    .dv-bar--attached { margin-bottom: 0; padding: 8px 12px; border-bottom: 1px solid var(--border-sub); }
    /* Body view — bảng phẳng (panel đã có viền + bo góc) nên bỏ viền/bo/nền riêng của bảng. */
    .dv-view { min-width: 0; min-height: 0; overflow: auto; }
    .dv-view ::ng-deep .ant-table { border: 0; border-radius: 0; background: transparent; }
    /* Thẻ trong panel cần padding để không dán mép. */
    .dv-view > .dv-cards { padding: 12px; }
    /* Strip RỔ NHÓM DỮ LIỆU — dính trên bảng (giữa toolbar và bảng khi [toolbar] bật). */
    .dv-grp { display: block; padding: 0; border-bottom: 1px solid var(--border-sub); }

    /* Kanban/gantt: panel PHẲNG — bỏ khung; toolbar tự là 1 hộp viền riêng, cách board 12px
       (không lồng board trong khung). */
    .dv-panel--flat { border: 0; background: transparent; border-radius: 0; overflow: visible; }
    .dv-panel--flat .dv-bar--attached {
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface);
      margin-bottom: 12px;
    }
    .dv-panel--flat .dv-view { overflow: visible; }

    /* Thanh tab đổi chế độ xem (kiểu ClickUp): icon + nhãn, mục chọn nền nổi. */
    .dv-tabs {
      display: inline-flex; gap: 2px; padding: 3px; flex: none;
      background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
    }
    .dv-tab {
      display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px;
      border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--icon-secondary);
      font: inherit; font-size: var(--fs-13); font-weight: 500;
      transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .dv-tab:hover { color: var(--text-strong); }
    .dv-tab.is-on { background: var(--bg-surface); color: var(--primary-base); box-shadow: var(--shadow-regular-xs); }
    .dv-tab-t { white-space: nowrap; }

    .dv-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(var(--dv-min, 260px), 1fr)); gap: 12px; }
    .dv-card {
      display: block; width: 100%; text-align: left; padding: 14px;
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      cursor: pointer; font: inherit; color: var(--text-body);
      transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), box-shadow var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .dv-card:hover { border-color: var(--primary-border); box-shadow: var(--shadow-regular-sm); }
    .dv-card:focus-visible { outline: 2px solid var(--primary-focus-ring); outline-offset: 1px; }

    /* Checkbox chọn trên thẻ — góc trên trái, hiện khi rê/đã chọn; thẻ chọn viền primary. */
    .dv-card { position: relative; }
    .dv-check {
      position: absolute; top: 8px; left: 8px; z-index: 2;
      display: grid; place-items: center; width: 22px; height: 22px;
      border-radius: var(--radius-sm); background: var(--bg-surface);
      box-shadow: var(--shadow-regular-xs); cursor: pointer;
      opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .dv-check input { width: 14px; height: 14px; margin: 0; cursor: pointer; accent-color: var(--primary-base); }
    .dv-card:hover .dv-check, .dv-card.is-sel .dv-check { opacity: 1; }
    .dv-card.is-sel { border-color: var(--primary-base); }
  `],
})
export class HrmDataView {
  /** Cột cho chế độ Bảng (HrmGridColumn — dùng lại toàn bộ, kể cả cell template). */
  readonly columns = input<HrmGridColumn[]>([]);
  readonly data = input<Row[]>([]);
  readonly rowKey = input('id');

  /** ── Toolbar dùng chung (opt-in) ── bật để hiện thanh search/lọc/sắp xếp/cột/xuất trên MỌI chế độ xem. */
  readonly toolbar = input(false);
  readonly searchable = input(true);
  readonly search = model('');
  readonly searchPlaceholder = input('Tìm kiếm…');
  /** Field để LỌC theo search ngay trong data-view; bỏ trống → không tự lọc (nghe searchChange, consumer tự lọc). */
  readonly searchFields = input<string[]>([]);
  readonly countLabel = input('');
  readonly filterable = input(false);
  readonly exportable = input(false);
  readonly searchChange = output<string>();
  readonly filterClick = output<void>();
  readonly exportClick = output<void>();
  /** Sort đa cấp + ẩn/hiện cột (two-way) — toolbar điều khiển, chế độ Bảng áp dụng. */
  readonly sortLevels = model<HrmGridSort[]>([]);
  readonly hiddenKeys = model<string[]>([]);
  /** ── RỔ NHÓM DỮ LIỆU (row-grouping) ── cấu hình nhóm hàng (two-way, chuyển tiếp xuống hrm-grid). */
  readonly rowGroups = model<HrmRowGroupLevel[]>([]);
  /** ── NHÓM CỘT (header 2 tầng) ── chuyển tiếp xuống hrm-grid: {id,title} để render tiêu đề nhóm span. */
  readonly columnGroups = input<{ id: string; title: string }[]>([]);
  /** Bật/tắt strip rổ nhóm phía trên bảng (opt-in, consumer điều khiển). */
  readonly showGroupPanel = model(false);
  /** id cdkDropList của rổ — để header cột bảng kéo cột vào rổ (grid nối qua groupConnectedTo). */
  protected readonly groupDropId = 'hrm-dv-rowgroup';
  /** Cột nguồn cho rổ nhóm — cột dữ liệu có tiêu đề; loại cột tiện ích (fixed/ghim, vd "Hành động").
   *  KHÔNG lọc theo sortable — cột non-sortable (ô phức tạp) VẪN nhóm được → tránh thiếu cột nhóm. */
  readonly rowGroupColumns = computed<{ key: string; title: string }[]>(() =>
    this.columns().filter((c) => !!c.title && !c.fixed && !c.computed).map((c) => ({ key: c.key, title: String(c.title) })));
  /** Chế độ board/gantt → panel PHẲNG (không lồng board trong khung viền). */
  protected readonly isFlat = computed(() => this.mode() === 'kanban' || this.mode() === 'gantt');
  /** Cột cho toolbar (Sắp xếp + Cột) — suy từ columns() có tiêu đề. */
  protected readonly toolbarColumns = computed<HrmSortColumn[]>(() =>
    this.columns().filter((c) => c.title && c.title.trim()).map((c) => ({ key: c.key, title: c.title })));
  /** Data sau lọc search (nếu có searchFields) — dùng cho mọi chế độ xem. */
  protected readonly viewData = computed<Row[]>(() => {
    const q = this.search().trim().toLowerCase();
    const fields = this.searchFields();
    if (!q || !fields.length) return this.data();
    return this.data().filter((r) => fields.some((f) => String(r[f] ?? '').toLowerCase().includes(q)));
  });
  /** Chế độ hiển thị (two-way). Mặc định Bảng. */
  readonly mode = model<HrmDataViewMode>('table');
  /** Chế độ được phép — quyết định số tab. Mặc định Bảng + Thẻ. */
  readonly modes = input<HrmDataViewMode[]>(['table', 'card']);

  /** Thẻ: template render 1 bản ghi (view Thẻ; Kanban dùng lại nếu không có boardCardTemplate). */
  readonly cardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  /** Thẻ RIÊNG cho Kanban — thường gọn hơn thẻ view Thẻ (cột hẹp, ưu tiên quét nhanh).
   *  Bỏ trống → dùng lại cardTemplate. */
  readonly boardCardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  /** Thẻ thực dùng cho Kanban. */
  protected readonly boardCard = computed(() => this.boardCardTemplate() ?? this.cardTemplate());
  readonly cardMin = input(260);
  /** Min-width bảng (mode table) → panel hẹp thì CUỘN NGANG thay vì ép cột (status/thao tác bị cắt). */
  readonly tableMinWidth = input('');
  readonly size = input<'small' | 'middle' | 'default'>('small');
  readonly selectable = input(false);
  /** Chuyển tiếp xuống hrm-grid — cho consumer TẮT bộ tùy biến cột nội tại của grid khi đã có
   *  công cụ Cột/Nhóm/Sắp xếp bên ngoài (tránh trùng ⋯/grip + thanh "Cột" (hg-bar) thứ hai +
   *  hai nguồn cùng ghi hiddenKeys). Mặc định true → không đổi hành vi consumer hiện có. */
  readonly customizable = input(true);
  readonly reorderable = input(true);
  readonly resizable = input(true);
  /** Định dạng nhãn group-header khi nhóm dữ liệu (key cột, giá trị thô) ⇒ chuỗi hiển thị. */
  readonly groupLabelFormatter = input<((key: string, value: unknown) => string) | null>(null);
  /** Khoá các bản ghi đang chọn (two-way) — DÙNG CHUNG cho mọi chế độ xem:
   *  bảng (cột checkbox) · thẻ/kanban (checkbox trên card) · gantt (checkbox cột nhãn). */
  readonly selectedKeys = model<unknown[]>([]);

  /** Kanban: field chia cột + định nghĩa cột. */
  readonly groupBy = input('status');
  readonly boardGroups = input<HrmBoardGroup[]>([]);

  /** Gantt: field ngày bắt đầu/kết thúc + % tiến độ + nhãn hàng. */
  readonly startField = input('start');
  readonly endField = input('end');
  readonly progressField = input('');
  readonly ganttLabelField = input('name');
  readonly ganttHeader = input('');
  /** Nhãn cột hạn ở bảng trái của Gantt (i18n). */
  readonly ganttDateHeader = input('');
  /** Gantt: template ô nhãn trái (chấm trạng thái/avatar/chức vụ…). */
  readonly ganttLabelTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  /** Gantt: hàm suy tông màu thanh theo bản ghi. */
  readonly ganttBarTone = input<((row: Row) => string) | null>(null);

  /** Nhãn tab (i18n, bên gọi cấp). Bỏ trống → tab chỉ icon. */
  readonly tableLabel = input('');
  readonly cardLabel = input('');
  readonly kanbanLabel = input('');
  readonly ganttLabel = input('');

  /** Click 1 bản ghi (mọi chế độ) → mở chi tiết. */
  readonly openRecord = output<Row>();
  /** Kanban: nhãn nút thêm ở chân mỗi cột (i18n). Bỏ trống → ẩn. */
  readonly boardAddLabel = input('');
  /** Kanban: bấm nút thêm ở 1 cột → phát key cột. */
  readonly boardAdd = output<string>();
  /** Kanban kéo thẻ sang cột khác. */
  readonly groupChange = output<{ row: Row; from: string; to: string }>();

  private readonly icons: Record<HrmDataViewMode, unknown> = {
    table: IconTable, card: IconLayoutGrid, kanban: IconLayoutKanban, gantt: IconChartBar,
  };
  protected readonly tabs = computed(() => {
    const lbl: Record<HrmDataViewMode, string> = {
      table: this.tableLabel(), card: this.cardLabel(), kanban: this.kanbanLabel(), gantt: this.ganttLabel(),
    };
    return this.modes().map((m) => ({ mode: m, icon: this.icons[m], label: lbl[m] }));
  });

  protected rowId(row: Row): unknown { return row[this.rowKey()]; }

  protected isSel(row: Row): boolean { return this.selectedKeys().includes(this.rowId(row)); }
  protected toggleSel(row: Row, checked: boolean): void {
    const k = this.rowId(row);
    const cur = this.selectedKeys();
    this.selectedKeys.set(checked ? [...cur, k] : cur.filter((x) => x !== k));
  }
}
