import { Component, TemplateRef, computed, effect, input, model, output, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import {
  CdkDropListGroup, CdkDropList, CdkDrag, CdkDragPlaceholder, CdkDragDrop,
  moveItemInArray, transferArrayItem,
} from '@angular/cdk/drag-drop';

type Row = Record<string, unknown>;

/** 1 cột Kanban: key khớp giá trị field group; label hiển thị; tone = màu chấm/nhãn. */
export interface HrmBoardGroup {
  key: string;
  label: string;
  tone?: 'success' | 'warning' | 'error' | 'info' | 'neutral';
}

/** hrm-board — bảng Kanban: nhóm dữ liệu theo 1 field (status/priority…) thành cột,
 *  mỗi bản ghi = 1 thẻ, kéo-thả thẻ giữa cột (CDK drag-drop) → cập nhật field + phát (groupChange).
 *  Thẻ render bằng [cardTemplate]; click thẻ phát (cardClick). Toàn token → tự Light/Dark.
 *
 *  <hrm-board [data]="rows" groupBy="status" [groups]="cols" [cardTemplate]="cardTpl"
 *     (groupChange)="onMove($event)" (cardClick)="open($event)" /> */
@Component({
  selector: 'hrm-board',
  imports: [NgTemplateOutlet, CdkDropListGroup, CdkDropList, CdkDrag, CdkDragPlaceholder],
  template: `
    <div class="bd" cdkDropListGroup>
      @for (g of groupsView(); track g.key) {
        <section class="bd-col">
          <header class="bd-col-h" [attr.data-tone]="g.tone || 'neutral'">
            <span class="bd-dot"></span>
            <span class="bd-col-title">{{ g.label }}</span>
            <span class="bd-col-count">{{ g.items.length }}</span>
          </header>
          <div class="bd-list" cdkDropList [cdkDropListData]="g.items"
            (cdkDropListDropped)="onDrop($event, g.key)">
            @for (row of g.items; track rowId(row)) {
              <div class="bd-card" [class.is-sel]="isSel(row)" cdkDrag (click)="cardClick.emit(row)">
                <div class="bd-card-ph" *cdkDragPlaceholder></div>
                @if (selectable()) {
                  <label class="bd-check" (click)="$event.stopPropagation()">
                    <input type="checkbox" [checked]="isSel(row)"
                      (change)="toggleSel(row, $any($event.target).checked)" />
                  </label>
                }
                @if (cardTemplate()) {
                  <ng-container [ngTemplateOutlet]="cardTemplate()!" [ngTemplateOutletContext]="{ $implicit: row }" />
                } @else {
                  <span class="bd-card-t">{{ row[titleField()] }}</span>
                }
              </div>
            }
          </div>
          @if (addLabel()) {
            <button type="button" class="bd-add" (click)="addCard.emit(g.key)">+ {{ addLabel() }}</button>
          }
        </section>
      }
    </div>
  `,
  host: { class: 'hrm-board' },
  styles: [`
    /* Board lấp đầy chiều cao vùng chứa; cột cao bằng nhau, cuộn NGANG giữa các cột. */
    :host { display: block; height: 100%; min-height: 0; }
    .bd { display: flex; gap: 12px; align-items: stretch; overflow-x: auto; overflow-y: hidden; height: 100%; padding-bottom: 4px; }
    .bd-col {
      flex: 0 0 288px; width: 288px; display: flex; flex-direction: column; min-height: 0; max-height: 100%;
      background: var(--bg-surface-subtle); border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
    }
    .bd-col-h { display: flex; align-items: center; gap: 8px; padding: 10px 12px; }
    .bd-dot { width: 8px; height: 8px; border-radius: var(--radius-full); flex: none; background: var(--neutral-400); }
    .bd-col-h[data-tone='success'] .bd-dot { background: var(--success-base); }
    .bd-col-h[data-tone='warning'] .bd-dot { background: var(--warning-base); }
    .bd-col-h[data-tone='error']   .bd-dot { background: var(--error-base); }
    .bd-col-h[data-tone='info']    .bd-dot { background: var(--info-base); }
    .bd-col-title { font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); }
    .bd-col-count { font-size: var(--fs-12); color: var(--text-sub); background: var(--bg-surface); padding: 0 7px; border-radius: var(--radius-full); }

    /* Danh sách thẻ — cuộn DỌC trong cột khi nhiều thẻ (header cột luôn thấy). */
    .bd-list { display: flex; flex-direction: column; gap: 8px; padding: 0 8px 10px; min-height: 40px; flex: 1 1 auto; overflow-y: auto; }
    .bd-col-h { flex: none; }
    .bd-card {
      background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-md);
      padding: 10px 12px; cursor: pointer; color: var(--text-body); box-shadow: var(--shadow-regular-xs);
      transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), box-shadow var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .bd-card:hover { border-color: var(--primary-border); }
    /* Checkbox chọn — góc trên trái thẻ, hiện khi rê/đã chọn; thẻ chọn viền primary. */
    .bd-card { position: relative; }
    .bd-check {
      position: absolute; top: 6px; left: 6px; z-index: 2;
      display: grid; place-items: center; width: 20px; height: 20px;
      border-radius: var(--radius-sm); background: var(--bg-surface);
      box-shadow: var(--shadow-regular-xs); cursor: pointer;
      opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .bd-check input { width: 13px; height: 13px; margin: 0; cursor: pointer; accent-color: var(--primary-base); }
    .bd-card:hover .bd-check, .bd-card.is-sel .bd-check { opacity: 1; }
    .bd-card.is-sel { border-color: var(--primary-base); }
    .bd-card-t { font-size: var(--fs-14); font-weight: 500; color: var(--text-strong); }

    /* Nút thêm ở chân cột — mờ, hiện rõ khi rê (không cạnh tranh với thẻ). */
    .bd-add {
      flex: none; margin: 0 8px 8px; padding: 7px 10px; text-align: left;
      border: 0; border-radius: var(--radius-md); background: transparent; cursor: pointer;
      font: inherit; font-size: var(--fs-13); font-weight: 500; color: var(--text-sub);
      transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .bd-add:hover { background: var(--bg-surface); color: var(--text-strong); }

    /* Kéo-thả: thẻ đang kéo nổi + bóng; chỗ trống = khung nét đứt. */
    .bd-card.cdk-drag-preview { box-shadow: var(--shadow-regular-md); border-color: var(--primary-base); }
    .bd-card.cdk-drag-placeholder { opacity: 0; }
    .bd-card-ph { height: 44px; border: 1px dashed var(--primary-border); border-radius: var(--radius-md); background: var(--primary-bg-subtle); }
    .cdk-drop-list-dragging .bd-card:not(.cdk-drag-placeholder) { transition: transform var(--duration-normal, .2s) var(--ease-out, ease); }
    .bd-list.cdk-drop-list-receiving, .bd-list.cdk-drop-list-dragging { border-radius: var(--radius-md); }
  `],
})
export class HrmBoard {
  readonly data = input<Row[]>([]);
  /** Field dùng để chia cột (VD 'status'). */
  readonly groupBy = input('status');
  /** Định nghĩa cột: key khớp giá trị field, label + tone màu. */
  readonly groups = input<HrmBoardGroup[]>([]);
  /** Template render 1 thẻ; context $implicit = row. Bỏ trống → hiện titleField. */
  readonly cardTemplate = input<TemplateRef<{ $implicit: Row }> | null>(null);
  readonly rowKey = input('id');
  /** Field làm tiêu đề thẻ khi không có cardTemplate. */
  readonly titleField = input('name');
  /** Cho chọn nhiều thẻ (checkbox góc thẻ). */
  readonly selectable = input(false);
  /** Khoá các thẻ đang chọn (two-way). */
  readonly selectedKeys = model<unknown[]>([]);
  /** Nhãn nút thêm ở chân mỗi cột (i18n, bên gọi cấp). Bỏ trống → ẩn nút. */
  readonly addLabel = input('');
  /** Bấm nút thêm ở 1 cột → phát key cột đó (để mở form thêm với giai đoạn tương ứng). */
  readonly addCard = output<string>();
  /** Click 1 thẻ → mở chi tiết. */
  readonly cardClick = output<Row>();
  /** Kéo thẻ sang cột khác → { row, from, to } (from/to = key cột). */
  readonly groupChange = output<{ row: Row; from: string; to: string }>();

  /** Xô chứa theo cột (mutable cho drag-drop), seed từ data + groups. */
  private readonly buckets = signal<Record<string, Row[]>>({});

  constructor() {
    effect(() => {
      const by = this.groupBy(), gs = this.groups(), rows = this.data();
      const map: Record<string, Row[]> = {};
      for (const g of gs) map[g.key] = [];
      for (const r of rows) {
        const k = String(r[by] ?? '');
        (map[k] ??= []).push(r);
      }
      this.buckets.set(map);
    });
  }

  protected readonly groupsView = computed(() =>
    this.groups().map((g) => ({ ...g, items: this.buckets()[g.key] ?? [] })));

  protected rowId(row: Row): unknown { return row[this.rowKey()]; }

  protected isSel(row: Row): boolean { return this.selectedKeys().includes(this.rowId(row)); }
  protected toggleSel(row: Row, checked: boolean): void {
    const k = this.rowId(row);
    const cur = this.selectedKeys();
    this.selectedKeys.set(checked ? [...cur, k] : cur.filter((x) => x !== k));
  }

  protected onDrop(e: CdkDragDrop<Row[]>, toKey: string): void {
    if (e.previousContainer === e.container) {
      moveItemInArray(e.container.data, e.previousIndex, e.currentIndex);
    } else {
      const row = e.previousContainer.data[e.previousIndex];
      const from = String(row[this.groupBy()] ?? '');
      transferArrayItem(e.previousContainer.data, e.container.data, e.previousIndex, e.currentIndex);
      row[this.groupBy()] = toKey;
      this.groupChange.emit({ row, from, to: toKey });
    }
    this.buckets.set({ ...this.buckets() });
  }
}
