/**
 * @file hrm-row-grouping — NHÓM DỮ LIỆU kiểu Kendo/Telerik (group panel kéo-thả) + renderer nhóm hàng.
 *
 *  MENTAL MODEL (bám hrm-data-config.types):
 *   - NHÓM DỮ LIỆU = gom HÀNG theo giá trị cột, tổ chức theo CHIỀU DỌC (khác NHÓM CỘT theo chiều ngang).
 *   - Nhiều cấp = nhóm lồng nhau: cấp trên hoà (cùng giá trị) mới xét cấp dưới.
 *   - Thứ tự chip trên "rổ" = thứ tự lồng; kéo grip đổi thứ tự → đổi cách lồng.
 *
 *  File này tự chứa 3 phần, KHÔNG import component hrm-ui khác (tránh phụ thuộc vòng):
 *   (1) HrmRowGrouping   — thanh "rổ" group panel (kéo-thả chip + đường thêm không-cần-kéo).
 *   (2) hrmGroupRows()   — helper thuần gom hàng theo levels (đệ quy) + type HrmRowGroupNode.
 *   (3) HrmGroupedRows   — render cây nhóm (header thu/mở + hàng lá qua rowTemplate).
 *
 *  THIẾT KẾ (Enterprise SaaS light-mode): calm, ít border, spacing chặt-thoáng, hierarchy rõ.
 *  Grip + icon phụ để visual-weight THẤP (màu --text-soft, mờ). Accent (primary) CHỈ cho active/focus.
 *  Chip nhóm là trạng thái cấu hình đang áp → giữ nền surface trung tính, KHÔNG nền màu loè.
 *
 *  RÀNG BUỘC KỸ THUẬT: Angular 21 standalone (không khai báo standalone:true), OnPush, Encapsulation.None,
 *  zoneless → mọi state qua signal. TUYỆT ĐỐI không có dấu backtick trong template/styles (giữ NG1010 an toàn).
 */
import {
  ChangeDetectionStrategy, Component, TemplateRef, ViewEncapsulation, computed, input, model, signal,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { CdkDropList, CdkDrag, CdkDragHandle, CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';
import {
  TablerIconComponent, IconGripVertical, IconX, IconArrowUp, IconArrowDown, IconArrowRight,
  IconChevronDown, IconChevronRight, IconPlus, IconArrowGuide, IconDotsVertical,
} from '@tabler/icons-angular';
import { HrmRowGroupLevel } from './hrm-data-config.types';

/** Cột có thể nhóm (chỉ cần key + nhãn hiển thị). */
export interface HrmRowGroupColumn { key: string; title: string; }

/** Nhãn hiển thị cho giá trị rỗng/null khi gom nhóm. */
export const HRM_GROUP_EMPTY_LABEL = '(Trống)';

/* =============================================================================================
 * (1) HrmRowGrouping — thanh "rổ" group panel (kéo-thả)
 * ============================================================================================= */
@Component({
  selector: 'hrm-row-grouping',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [CdkDropList, CdkDrag, CdkDragHandle, TablerIconComponent],
  host: { class: 'hrm-row-grouping', '(document:click)': 'closeMenus()' },
  template: `
    <div class="rg-panel" [class.is-empty]="!levels().length">
      <!-- VÙNG DRAG full-bleed: nhận thả header cột + chứa chip (drop target = rg-main). -->
      <div class="rg-main" [class.is-empty]="!levels().length"
        cdkDropList [id]="dropListId()" cdkDropListOrientation="horizontal"
        [cdkDropListData]="levels()" (cdkDropListDropped)="onDrop($event)">
        @if (!levels().length) {
          <!-- RỖNG: dải gợi ý xám nhạt + icon guide (⤵) — đường "kéo tiêu đề cột vào đây". -->
          <div class="rg-hint">
            <tabler-icon class="rg-hint-ic" [icon]="icGuide" [size]="16" />
            <span>{{ emptyText() }}</span>
          </div>
        } @else {
          <!-- CÓ LEVELS: mỗi cấp = 1 chip; các chip nối bằng mũi tên → (thứ tự chip = thứ tự lồng). -->
          @for (lv of chips(); track lv.key; let i = $index) {
            @if (i > 0) { <tabler-icon class="rg-arrow" [icon]="icArrowRight" [size]="14" /> }
            <div class="rg-chip" cdkDrag [cdkDragData]="lv.key">
              <span class="rg-grip" cdkDragHandle [attr.aria-label]="reorderLabel()">
                <tabler-icon [icon]="icGrip" [size]="16" />
              </span>
              <span class="rg-chip-title">{{ lv.title }}</span>
              <button type="button" class="rg-chip-dir" [attr.aria-label]="dirLabel()"
                [attr.aria-pressed]="lv.dir === 'asc'" (click)="toggleDir(i)">
                <tabler-icon [icon]="lv.dir === 'asc' ? icUp : icDown" [size]="14" />
              </button>
              <button type="button" class="rg-chip-x" [attr.aria-label]="removeLabel()" (click)="removeLevel(i)">
                <tabler-icon [icon]="icX" [size]="14" />
              </button>
            </div>
          }
        }
      </div>

      <!-- CỤM HÀNH ĐỘNG canh PHẢI: "+ Thêm cấp nhóm" kề button ⋯ tùy chọn. -->
      <div class="rg-actions">
        <!-- ĐƯỜNG THÊM KHÔNG-CẦN-KÉO: nút "+ Thêm cấp nhóm" mở dropdown chọn cột chưa nhóm. -->
        <div class="rg-add-wrap" [class.is-open]="addMenuOpen()">
          <button type="button" class="rg-add" [disabled]="!canAdd()" [attr.aria-expanded]="addMenuOpen()"
            (click)="toggleAddMenu($event)">
            <tabler-icon [icon]="icPlus" [size]="14" />
            <span>{{ addLabel() }}</span>
            <tabler-icon class="rg-add-caret" [icon]="icChevronDown" [size]="14" />
          </button>
          @if (addMenuOpen()) {
            <div class="rg-menu rg-menu-end" role="menu" (click)="stop($event)">
              @for (c of availableColumns(); track c.key) {
                <button type="button" class="rg-menu-item" role="menuitem" (click)="addLevel(c.key)">
                  <tabler-icon [icon]="icPlus" [size]="14" />
                  <span>{{ c.title }}</span>
                </button>
              } @empty {
                <div class="rg-menu-empty">{{ allUsedText() }}</div>
              }
            </div>
          }
        </div>

        <!-- TÙY CHỌN PHỤ: menu ⋯ (số bản ghi · mặc định thu gọn · bỏ tất cả nhóm). -->
        <div class="rg-opts-wrap" [class.is-open]="moreMenuOpen()">
          <button type="button" class="rg-icon-btn" [attr.aria-label]="optionsLabel()"
            [attr.aria-expanded]="moreMenuOpen()" (click)="toggleMoreMenu($event)">
            <tabler-icon [icon]="icDots" [size]="16" />
          </button>
          @if (moreMenuOpen()) {
            <div class="rg-menu rg-menu-end" role="menu" (click)="stop($event)">
              <label class="rg-menu-opt">
                <input type="checkbox" [checked]="showCount()"
                  (change)="showCount.set($any($event.target).checked)" />
                <span>{{ showCountLabel() }}</span>
              </label>
              <label class="rg-menu-opt">
                <input type="checkbox" [checked]="collapsedDefault()"
                  (change)="collapsedDefault.set($any($event.target).checked)" />
                <span>{{ collapsedLabel() }}</span>
              </label>
              <div class="rg-menu-sep"></div>
              <button type="button" class="rg-menu-item rg-menu-danger" [disabled]="!levels().length"
                (click)="clearAll()">
                <tabler-icon [icon]="icX" [size]="14" />
                <span>{{ clearAllLabel() }}</span>
              </button>
            </div>
          }
        </div>
      </div>
    </div>
  `,
  styles: [`
.hrm-row-grouping { display: block; }
/* Band NHÓM DỮ LIỆU full-bleed: bỏ viền/bo/padding ngoài → tràn sát khung (consumer .dv-grp lo border-bottom). */
.rg-panel { display: flex; align-items: stretch; flex-wrap: nowrap; gap: 0;
  min-height: 46px; padding: 0; border: 0; border-radius: 0;
  background: var(--bg-surface); font-family: var(--font-sans); }
.rg-panel.is-empty { background: var(--bg-surface-subtle); }
/* Vùng drag/chip — CHIẾM FULL width (đẩy cụm hành động sang phải); canh nội dung 12px như toolbar. */
.rg-main { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-2, 8px);
  flex: 1 1 auto; min-width: 0; padding-inline: var(--space-3, 12px); }
/* Cụm "+ Thêm cấp nhóm" + ⋯ dồn PHẢI, sát mép phải khung (12px). */
.rg-actions { display: flex; align-items: center; gap: var(--space-2, 8px);
  flex: none; padding-inline: var(--space-2, 8px) var(--space-3, 12px); }

/* Dải gợi ý (rỗng) — visual-weight thấp, dashed nhẹ để mời "thả vào đây". */
/* Vùng gợi ý (rỗng) — KHÔNG viền răng cưa; cả band xám (rg-panel.is-empty) là vùng thả để nhóm.
   Text + icon canh TRÁI, thẳng lề với cột đầu bảng (rg-main đã pad 12px). */
.rg-hint { display: flex; align-items: center; justify-content: flex-start; gap: var(--space-2, 8px);
  flex: 1 1 auto; min-width: 0; padding-block: var(--space-2, 8px); color: var(--text-soft);
  font-size: var(--fs-13, 13px); }
.rg-hint-ic { flex: none; color: var(--text-soft); opacity: .8; }
/* Khi KÉO tiêu đề cột qua vùng thả → band sáng xanh nhạt (affordance "thả vào đây để nhóm"). */
.rg-main.cdk-drop-list-receiving, .rg-main.cdk-drop-list-dragging {
  background: var(--primary-bg-subtle); box-shadow: inset 0 0 0 1px var(--primary-border); }

/* Mũi tên nối chip. */
.rg-arrow { flex: none; color: var(--text-soft); opacity: .7; }

/* Chip 1 cấp nhóm. */
.rg-chip { display: inline-flex; align-items: center; gap: var(--space-1, 4px); flex: none; height: 30px;
  padding: 0 var(--space-1, 4px) 0 2px; background: var(--bg-surface-subtle);
  border: 1px solid var(--border-sub); border-radius: var(--radius-md, 8px); }
.rg-chip.cdk-drag-preview { box-shadow: var(--shadow-regular-md); background: var(--bg-surface); }
.rg-grip { flex: none; display: inline-grid; place-items: center; width: 20px; height: 26px;
  color: var(--text-soft); cursor: grab; border-radius: var(--radius-sm, 6px); }
.rg-grip:hover { color: var(--text-body); background: var(--bg-surface); }
.rg-grip:active { cursor: grabbing; }
.rg-chip-title { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong);
  white-space: nowrap; padding: 0 var(--space-1, 4px); }
.rg-chip-dir, .rg-chip-x { flex: none; display: inline-grid; place-items: center; width: 22px; height: 22px;
  border: 0; background: transparent; border-radius: var(--radius-sm, 6px); color: var(--text-soft); cursor: pointer; }
.rg-chip-dir:hover { color: var(--primary-base); background: var(--primary-bg-subtle); }
.rg-chip-x:hover { color: var(--error-base); background: var(--bg-surface); }
.rg-chip-dir:focus-visible, .rg-chip-x:focus-visible {
  outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

/* Nút "+ Thêm cấp nhóm" + dropdown. */
.rg-add-wrap, .rg-opts-wrap { position: relative; flex: none; }
.rg-add { display: inline-flex; align-items: center; gap: var(--space-1, 4px); height: 30px;
  padding: 0 var(--space-2, 8px); border: 1px dashed var(--border-sub); border-radius: var(--radius-md, 8px);
  background: transparent; color: var(--text-sub); font: inherit; font-size: var(--fs-13, 13px); cursor: pointer;
  white-space: nowrap; }
.rg-add:hover:not(:disabled) { border-color: var(--primary-border); color: var(--text-strong); }
.rg-add:disabled { opacity: .5; cursor: not-allowed; }
.rg-add-caret { color: var(--text-soft); }
.rg-add:focus-visible, .rg-icon-btn:focus-visible {
  outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }

.rg-icon-btn { display: inline-grid; place-items: center; width: 30px; height: 30px; border: 0; background: transparent;
  border-radius: var(--radius-md, 8px); color: var(--text-soft); cursor: pointer; }
.rg-icon-btn:hover, .rg-opts-wrap.is-open .rg-icon-btn { color: var(--text-strong); background: var(--bg-surface-subtle); }

/* Dropdown menu chung (không backdrop; đóng qua document:click). */
.rg-menu { position: absolute; top: calc(100% + 4px); inset-inline-start: 0; z-index: 30; min-width: 200px;
  max-height: 280px; overflow-y: auto; padding: var(--space-1, 4px); background: var(--bg-surface);
  border: 1px solid var(--border-sub); border-radius: var(--radius-lg, 10px); box-shadow: var(--shadow-regular-md); }
.rg-menu-end { inset-inline-start: auto; inset-inline-end: 0; }
.rg-menu-item { display: flex; align-items: center; gap: var(--space-2, 8px); width: 100%; height: 34px;
  padding: 0 var(--space-2, 8px); border: 0; background: transparent; border-radius: var(--radius-sm, 6px);
  color: var(--text-body); font: inherit; font-size: var(--fs-13, 13px); text-align: start; cursor: pointer; }
.rg-menu-item:hover:not(:disabled) { background: var(--primary-bg-subtle); color: var(--primary-base); }
.rg-menu-item > tabler-icon { color: var(--text-soft); }
.rg-menu-item:hover:not(:disabled) > tabler-icon { color: inherit; }
.rg-menu-item:disabled { opacity: .5; cursor: not-allowed; }
.rg-menu-danger:hover:not(:disabled) { background: var(--error-bg, var(--bg-surface-subtle)); color: var(--error-base); }
.rg-menu-empty { padding: var(--space-3, 12px) var(--space-2, 8px); text-align: center;
  font-size: var(--fs-12, 12px); color: var(--text-soft); }
.rg-menu-opt { display: flex; align-items: center; gap: var(--space-2, 8px); height: 34px;
  padding: 0 var(--space-2, 8px); border-radius: var(--radius-sm, 6px); color: var(--text-body);
  font-size: var(--fs-13, 13px); cursor: pointer; }
.rg-menu-opt:hover { background: var(--bg-surface-subtle); }
.rg-menu-opt input { accent-color: var(--primary-base); width: 15px; height: 15px; cursor: pointer; }
.rg-menu-sep { height: 1px; margin: var(--space-1, 4px) 0; background: var(--border-soft); }

.cdk-drag-placeholder { opacity: .35; }
  `],
})
export class HrmRowGrouping {
  /** Cột có thể nhóm (key + nhãn). */
  readonly columns = input<HrmRowGroupColumn[]>([]);
  /** Cấu hình nhóm (two-way) — thứ tự phần tử = thứ tự lồng. */
  readonly levels = model<HrmRowGroupLevel[]>([]);
  /** Hiển thị số bản ghi trong header nhóm (two-way — dùng chung với hrm-grouped-rows). */
  readonly showCount = model(true);
  /** Mặc định thu gọn mọi nhóm khi render (two-way — dùng chung với hrm-grouped-rows). */
  readonly collapsedDefault = model(false);

  /**
   * id của cdkDropList — để header bảng có thể cdkDropListConnectedTo tới rổ này (kéo cột vào để nhóm).
   * Mặc định cố định; đổi nếu có nhiều rổ trên cùng trang.
   */
  readonly dropListId = input('hrm-row-grouping-list');

  /** Nhãn i18n (mặc định tiếng Việt). */
  readonly emptyText = input('Kéo tiêu đề cột vào đây để nhóm dữ liệu');
  readonly addLabel = input('Thêm cấp nhóm');
  readonly reorderLabel = input('Kéo đổi thứ tự lồng nhóm');
  readonly dirLabel = input('Đổi hướng sắp xếp nhóm');
  readonly removeLabel = input('Bỏ cấp nhóm');
  readonly optionsLabel = input('Tuỳ chọn nhóm');
  readonly showCountLabel = input('Hiển thị số bản ghi');
  readonly collapsedLabel = input('Mặc định thu gọn nhóm');
  readonly clearAllLabel = input('Bỏ tất cả nhóm');
  readonly allUsedText = input('Đã nhóm theo mọi cột');

  protected readonly icGrip = IconGripVertical;
  protected readonly icX = IconX;
  protected readonly icUp = IconArrowUp;
  protected readonly icDown = IconArrowDown;
  protected readonly icArrowRight = IconArrowRight;
  protected readonly icChevronDown = IconChevronDown;
  protected readonly icPlus = IconPlus;
  protected readonly icGuide = IconArrowGuide;
  protected readonly icDots = IconDotsVertical;

  /** Trạng thái mở của 2 dropdown (đóng lẫn nhau + đóng qua click ngoài). */
  protected readonly addMenuOpen = signal(false);
  protected readonly moreMenuOpen = signal(false);

  /** Set key đã nhóm — để lọc cột còn lại + chống thêm trùng. */
  private readonly levelKeySet = computed(() => new Set(this.levels().map((l) => l.key)));
  /** Cột chưa nhóm (nguồn cho dropdown "+ Thêm cấp nhóm"). */
  protected readonly availableColumns = computed(() =>
    this.columns().filter((c) => !this.levelKeySet().has(c.key)),
  );
  protected readonly canAdd = computed(() => this.availableColumns().length > 0);

  /** Chip hiển thị = level + nhãn cột tra từ columns (fallback: chính key nếu thiếu). */
  protected readonly chips = computed(() => {
    const titleOf = new Map(this.columns().map((c) => [c.key, c.title] as const));
    return this.levels().map((l) => ({ key: l.key, dir: l.dir, title: titleOf.get(l.key) ?? l.key }));
  });

  /** Thêm 1 cấp nhóm từ key cột (bỏ qua nếu đã nhóm). */
  protected addLevel(key: string): void {
    if (this.levelKeySet().has(key)) return;
    this.levels.update((arr) => [...arr, { key, dir: 'asc' as HrmRowGroupLevel['dir'] }]);
    this.addMenuOpen.set(false);
  }
  protected removeLevel(i: number): void {
    this.levels.set(this.levels().filter((_, j) => j !== i));
  }
  /** Đảo hướng sắp xếp của 1 cấp (asc <-> desc). */
  protected toggleDir(i: number): void {
    this.levels.update((arr) =>
      arr.map((l, j) => (j === i ? { ...l, dir: (l.dir === 'asc' ? 'desc' : 'asc') as HrmRowGroupLevel['dir'] } : l)),
    );
  }
  protected clearAll(): void {
    this.levels.set([]);
    this.moreMenuOpen.set(false);
  }

  /**
   * Xử lý drop: nội bộ = đổi thứ tự lồng (moveItemInArray). Từ danh sách khác (header bảng) = thêm cấp mới
   * theo key cột được thả (best-effort: đọc cdkDragData dạng string hoặc object có .key).
   */
  protected onDrop(e: CdkDragDrop<HrmRowGroupLevel[]>): void {
    if (e.previousContainer === e.container) {
      const arr = [...this.levels()];
      moveItemInArray(arr, e.previousIndex, e.currentIndex);
      this.levels.set(arr);
      return;
    }
    const data = e.item.data as unknown;
    let key: string | null = null;
    if (typeof data === 'string') key = data;
    else if (data && typeof data === 'object' && 'key' in (data as Record<string, unknown>)) {
      key = String((data as Record<string, unknown>)['key']);
    }
    if (key && this.columns().some((c) => c.key === key) && !this.levelKeySet().has(key)) {
      this.addLevel(key);
    }
  }

  /* --- điều khiển dropdown --- */
  protected toggleAddMenu(e: Event): void {
    e.stopPropagation();
    this.moreMenuOpen.set(false);
    this.addMenuOpen.update((v) => !v);
  }
  protected toggleMoreMenu(e: Event): void {
    e.stopPropagation();
    this.addMenuOpen.set(false);
    this.moreMenuOpen.update((v) => !v);
  }
  protected stop(e: Event): void { e.stopPropagation(); }
  protected closeMenus(): void {
    this.addMenuOpen.set(false);
    this.moreMenuOpen.set(false);
  }
}

/* =============================================================================================
 * (2) Helper thuần + type — gom hàng theo levels
 * ============================================================================================= */

/** 1 nút trong cây nhóm. Nút lá giữ rows; nút trong giữ children (rows rỗng). */
export interface HrmRowGroupNode {
  /** Khóa duy nhất theo ĐƯỜNG DẪN (parent/field=value) — dùng cho state thu/mở. */
  key: string;
  /** Cột (key) mà cấp này nhóm theo. */
  field: string;
  /** Nhãn hiển thị = giá trị nhóm (rỗng ⇒ HRM_GROUP_EMPTY_LABEL). */
  label: string;
  /** Tổng số hàng lá dưới nút (đệ quy). */
  count: number;
  /** Nhóm con (rỗng nếu là cấp cuối). */
  children: HrmRowGroupNode[];
  /** Hàng lá (chỉ có ở cấp cuối). */
  rows: Record<string, unknown>[];
}

/** So sánh giá trị nhóm: ưu tiên số học khi cả 2 là số, còn lại so chuỗi theo locale vi. */
function hrmCompareGroupValue(a: string, b: string): number {
  const na = Number(a);
  const nb = Number(b);
  const aNum = a !== '' && !Number.isNaN(na);
  const bNum = b !== '' && !Number.isNaN(nb);
  if (aNum && bNum) return na - nb;
  return a.localeCompare(b, 'vi');
}

/** Đệ quy 1 cấp: gom rows theo levels[depth], cấp cuối gắn rows, cấp trên gắn children + count cộng dồn. */
function hrmBuildGroups(
  rows: Record<string, unknown>[],
  levels: HrmRowGroupLevel[],
  depth: number,
  parentKey: string,
): HrmRowGroupNode[] {
  if (depth >= levels.length) return [];
  const level = levels[depth];
  const field = level.key;
  const buckets = new Map<string, Record<string, unknown>[]>();
  const order: string[] = [];
  for (const row of rows) {
    const raw = row[field];
    const vkey = raw === null || raw === undefined || raw === '' ? '' : String(raw);
    let bucket = buckets.get(vkey);
    if (!bucket) { bucket = []; buckets.set(vkey, bucket); order.push(vkey); }
    bucket.push(row);
  }
  const isLeaf = depth === levels.length - 1;
  const nodes: HrmRowGroupNode[] = order.map((vkey) => {
    const groupRows = buckets.get(vkey) as Record<string, unknown>[];
    const key = parentKey + '/' + field + '=' + vkey;
    const label = vkey === '' ? HRM_GROUP_EMPTY_LABEL : vkey;
    if (isLeaf) {
      return { key, field, label, count: groupRows.length, children: [], rows: groupRows };
    }
    const children = hrmBuildGroups(groupRows, levels, depth + 1, key);
    return { key, field, label, count: groupRows.length, children, rows: [] };
  });
  const factor = level.dir === 'desc' ? -1 : 1;
  nodes.sort((a, b) => hrmCompareGroupValue(a.label, b.label) * factor);
  return nodes;
}

/**
 * Gom danh sách hàng thành cây nhóm theo levels (cấp trên hoà mới xét cấp dưới).
 *  - levels rỗng ⇒ trả [] (consumer render bảng phẳng như thường).
 *  - count = tổng hàng lá; nhóm sort theo dir mỗi cấp.
 */
export function hrmGroupRows(
  rows: Record<string, unknown>[],
  levels: HrmRowGroupLevel[],
): HrmRowGroupNode[] {
  if (!levels.length) return [];
  return hrmBuildGroups(rows, levels, 0, '');
}

/* =============================================================================================
 * (3) HrmGroupedRows — render cây nhóm (thu/mở + hàng lá qua rowTemplate)
 * ============================================================================================= */
@Component({
  selector: 'hrm-grouped-rows',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgTemplateOutlet, TablerIconComponent],
  host: { class: 'hrm-grouped-rows' },
  template: `
    <!-- Template đệ quy 1 nút: header (thu/mở) + body (children đệ quy | hàng lá). -->
    <ng-template #nodeTpl let-node let-depth="depth">
      <div class="gr-group">
        <button type="button" class="gr-head" [style.--gr-depth]="depth" (click)="toggle(node.key)"
          [attr.aria-expanded]="!isCollapsed(node.key)">
          <tabler-icon class="gr-caret" [icon]="isCollapsed(node.key) ? icRight : icDown" [size]="16" />
          <span class="gr-label">{{ node.label }}</span>
          @if (showCount()) { <span class="gr-count">{{ node.count }}</span> }
        </button>

        @if (!isCollapsed(node.key)) {
          <div class="gr-body">
            @if (node.children.length) {
              @for (child of node.children; track child.key) {
                <ng-container [ngTemplateOutlet]="nodeTpl"
                  [ngTemplateOutletContext]="{ $implicit: child, depth: depth + 1 }" />
              }
            } @else {
              @for (row of node.rows; track $index) {
                @if (rowTemplate(); as tpl) {
                  <div class="gr-row" [style.--gr-depth]="depth + 1">
                    <ng-container [ngTemplateOutlet]="tpl" [ngTemplateOutletContext]="{ $implicit: row }" />
                  </div>
                } @else {
                  <div class="gr-row gr-row-fallback" [style.--gr-depth]="depth + 1">{{ fallbackRow(row) }}</div>
                }
              }
            }
          </div>
        }
      </div>
    </ng-template>

    <div class="gr-root">
      @for (node of nodes(); track node.key) {
        <ng-container [ngTemplateOutlet]="nodeTpl" [ngTemplateOutletContext]="{ $implicit: node, depth: 0 }" />
      } @empty {
        <div class="gr-empty">{{ emptyText() }}</div>
      }
    </div>
  `,
  styles: [`
.hrm-grouped-rows { display: block; font-family: var(--font-sans); }
.gr-root { display: flex; flex-direction: column; }
.gr-group { display: flex; flex-direction: column; }

.gr-head { display: flex; align-items: center; gap: var(--space-2, 8px); width: 100%; min-height: 38px;
  padding: var(--space-2, 8px) var(--space-3, 12px);
  padding-inline-start: calc(var(--space-3, 12px) + var(--gr-depth, 0) * var(--space-5, 20px));
  border: 0; border-top: 1px solid var(--border-soft); background: var(--bg-surface-subtle);
  color: var(--text-strong); font: inherit; text-align: start; cursor: pointer; }
.gr-head:hover { background: var(--bg-surface); }
.gr-head:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: -2px; }
.gr-caret { flex: none; color: var(--text-soft); }
.gr-label { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); white-space: nowrap; }
.gr-count { display: inline-grid; place-items: center; min-width: 20px; height: 18px; padding: 0 6px;
  border-radius: var(--radius-full); background: var(--primary-bg-soft); color: var(--primary-base);
  font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); line-height: 1; }

/* Mở/thu mượt: body xuất hiện với hiệu ứng trượt-mờ nhẹ. */
.gr-body { display: flex; flex-direction: column; animation: gr-reveal var(--duration-fast, .16s) var(--ease-out, ease); }
@keyframes gr-reveal { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }

/* Hàng dữ liệu KHÔNG thụt theo cấp → THẲNG cột với header (cấu trúc lồng thể hiện qua group-header
   thụt lề + đếm). Nếu thụt hàng lá, lưới div-grid bị đẩy phải, lệch cột header. */
.gr-row { padding-inline-start: 0; }
.gr-row-fallback { min-height: 34px; display: flex; align-items: center;
  padding-block: var(--space-2, 8px); padding-inline-end: var(--space-3, 12px);
  padding-inline-start: calc(var(--space-3, 12px) + var(--gr-depth, 0) * var(--space-5, 20px));
  border-top: 1px solid var(--border-soft); font-size: var(--fs-13, 13px); color: var(--text-body); }

.gr-empty { padding: var(--space-6, 24px) var(--space-4, 16px); text-align: center;
  font-size: var(--fs-13, 13px); color: var(--text-soft); }
  `],
})
export class HrmGroupedRows {
  /** Cây nhóm (từ hrmGroupRows). */
  readonly nodes = input<HrmRowGroupNode[]>([]);
  /** Template render 1 hàng lá — nhận $implicit = bản ghi. Null ⇒ fallback chuỗi giá trị. */
  readonly rowTemplate = input<TemplateRef<{ $implicit: Record<string, unknown> }> | null>(null);
  /** Hiện badge số bản ghi trên header nhóm. */
  readonly showCount = input(true);
  /** Mặc định thu gọn mọi nhóm (người dùng vẫn mở/thu từng nhóm được). */
  readonly collapsedDefault = input(false);
  /** Nhãn khi không có nhóm nào. */
  readonly emptyText = input('Không có dữ liệu để hiển thị');

  protected readonly icDown = IconChevronDown;
  protected readonly icRight = IconChevronRight;

  /**
   * State thu/mở: lưu tập key ĐÃ ĐẢO so với mặc định (tiết kiệm + tôn trọng collapsedDefault động).
   * collapsed = collapsedDefault XOR (key nằm trong flipped).
   */
  private readonly flipped = signal<Set<string>>(new Set<string>());

  protected isCollapsed(key: string): boolean {
    return this.collapsedDefault() !== this.flipped().has(key);
  }
  protected toggle(key: string): void {
    this.flipped.update((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  }

  /** Fallback khi không truyền rowTemplate: nối các giá trị bản ghi (bỏ rỗng). */
  protected fallbackRow(row: Record<string, unknown>): string {
    return Object.values(row)
      .map((v) => (v === null || v === undefined ? '' : String(v)))
      .filter((s) => s !== '')
      .join('  ·  ');
  }
}
